package cn.binbin.crm;

import jakarta.validation.constraints.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class CommercialService {
 public record OrderInput(@NotNull UUID tenantId,@NotNull UUID planId,@Min(1) @Max(36) int periodMonths,@Min(0) Long amountCents,@NotNull LocalDate dueDate,@Size(max=500) String notes){}
 public record PaidInput(@NotBlank @Size(max=100) String externalReference,@Min(0) long expectedVersion){}
 public record CancelInput(@NotBlank @Size(max=300) String reason,@Min(0) long expectedVersion){}
 public record EntitlementInput(boolean configurationEnabled,boolean portalEnabled,boolean aiEnabled,@Min(0) @Max(1000000) int aiMonthlyRunLimit,@Min(0) long expectedVersion){}
 private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;
 public CommercialService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth){this.db=db;this.tx=tx;this.auth=auth;}
 private static Map<String,Object> p(Object... v){return SaasService.parameters(v);}
 private static String text(String s){return s==null?"":s.strip();}
 private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private Map<String,Object> one(String sql,Map<String,?> p){var rows=db.queryForList(sql,p);if(rows.isEmpty())throw ApiError.missing();return rows.getFirst();}
 private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.queryForList(sql,p).stream().map(SaasService::view).toList();}
 private <T>T platform(AuthService.Session s,Supplier<T> fn){auth.platform(s);return tx.execute(x->fn.get());}
 private void audit(AuthService.Session s,UUID tenant,String action,UUID id,Object details,UUID trace){String body;try{body=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(details);}catch(Exception e){body="{}";}db.update("INSERT INTO sys_platform_audit(id,actor_user_id,tenant_id,action,target_id,details,trace_id) VALUES(:audit,:user,:tenant,:action,:id,cast(:details AS jsonb),:trace)",p("audit",UUID.randomUUID(),"user",s.userId(),"tenant",tenant,"action",action,"id",id,"details",body,"trace",trace));}
 public Object entitlements(AuthService.Session s){var a=auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不能读取商业化配置");return tx.execute(x->{var row=one("SELECT p.code,p.name,p.configuration_enabled,p.portal_enabled,p.ai_enabled,p.ai_monthly_run_limit,coalesce(u.ai_runs,0) ai_runs,t.subscription_end FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id LEFT JOIN sys_usage_monthly u ON u.tenant_id=t.id AND u.usage_month=date_trunc('month',current_date)::date WHERE t.id=:tenant",p("tenant",a.tenant().id()));return SaasService.view(row);});}
 public Object overview(AuthService.Session s){return platform(s,()->{var metrics=SaasService.view(one("SELECT count(*) FILTER(WHERE t.status='ACTIVE') AS active_tenants,count(*) FILTER(WHERE t.status='ACTIVE' AND t.subscription_end<=now()+interval '30 days') AS expiring_tenants,coalesce(sum(p.monthly_price_cents) FILTER(WHERE t.status='ACTIVE' AND t.subscription_end>now()),0) AS mrr_cents,(SELECT count(*) FROM sys_subscription_order WHERE status='PENDING') AS pending_orders,(SELECT coalesce(sum(amount_cents),0) FROM sys_subscription_order WHERE status='PAID' AND paid_at>=date_trunc('month',now())) AS paid_this_month_cents FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id",Map.of()));var plans=rows("SELECT p.id,p.code,p.name,p.monthly_price_cents,p.seat_limit,p.customer_limit,p.configuration_enabled,p.portal_enabled,p.ai_enabled,p.ai_monthly_run_limit,p.version,count(t.id) AS tenant_count FROM sys_plan p LEFT JOIN sys_tenant t ON t.plan_id=p.id GROUP BY p.id ORDER BY p.monthly_price_cents,p.code",Map.of());return p("metrics",metrics,"plans",plans,"paymentMode","MANUAL_ONLY","currency","CNY");});}
 public Object entitlements(AuthService.Session s,UUID id,EntitlementInput i,UUID trace){return platform(s,()->{if(i.aiEnabled()&&i.aiMonthlyRunLimit()<1)throw ApiError.bad("启用 AI 时月度额度至少为 1");int changed=db.update("UPDATE sys_plan SET configuration_enabled=:configuration,portal_enabled=:portal,ai_enabled=:ai,ai_monthly_run_limit=:limit,version=version+1 WHERE id=:id AND version=:version",p("configuration",i.configurationEnabled(),"portal",i.portalEnabled(),"ai",i.aiEnabled(),"limit",i.aiMonthlyRunLimit(),"id",id,"version",i.expectedVersion()));if(changed!=1)throw ApiError.conflict("套餐权益已变化，请刷新");audit(s,null,"PLAN_ENTITLEMENTS_UPDATED",id,i,trace);return SaasService.view(one("SELECT * FROM sys_plan WHERE id=:id",p("id",id)));});}
 public Object tenants(AuthService.Session s){return platform(s,()->rows("SELECT t.id,t.code,t.name,t.status,t.subscription_end,t.active_member_count,t.customer_count,t.attachment_bytes,p.id AS plan_id,p.name AS plan_name,p.seat_limit,p.customer_limit,p.storage_limit_bytes,p.configuration_enabled,p.portal_enabled,p.ai_enabled,p.ai_monthly_run_limit,coalesce(u.ai_runs,0) AS ai_runs,(SELECT count(*) FROM portal_account a WHERE a.tenant_id=t.id AND a.status='ACTIVE') AS portal_accounts FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id LEFT JOIN sys_usage_monthly u ON u.tenant_id=t.id AND u.usage_month=date_trunc('month',current_date)::date ORDER BY t.created_at DESC,t.id",Map.of()));}
 public Object orders(AuthService.Session s){return platform(s,()->rows("SELECT o.*,t.name AS tenant_name,p.name AS plan_name,u.display_name AS creator_name FROM sys_subscription_order o JOIN sys_tenant t ON t.id=o.tenant_id JOIN sys_plan p ON p.id=o.plan_id JOIN iam_user u ON u.id=o.created_by_user_id ORDER BY o.created_at DESC,o.id LIMIT 1000",Map.of()));}
 private Map<String,Object> order(UUID id){return SaasService.view(one("SELECT o.*,t.name AS tenant_name,p.name AS plan_name,u.display_name AS creator_name FROM sys_subscription_order o JOIN sys_tenant t ON t.id=o.tenant_id JOIN sys_plan p ON p.id=o.plan_id JOIN iam_user u ON u.id=o.created_by_user_id WHERE o.id=:id",p("id",id)));}
 public Object create(AuthService.Session s,OrderInput i,String key,UUID trace){if(!Set.of(1,3,6,12,24,36).contains(i.periodMonths()))throw ApiError.bad("订阅周期支持 1、3、6、12、24 或 36 个月");if(i.dueDate().isBefore(LocalDate.now().minusDays(1))||i.dueDate().isAfter(LocalDate.now().plusYears(2)))throw ApiError.bad("订单到期日无效");if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号格式无效");return platform(s,()->{var plan=one("SELECT * FROM sys_plan WHERE id=:id AND active",p("id",i.planId()));one("SELECT id FROM sys_tenant WHERE id=:id",p("id",i.tenantId()));String hash=Crypto.hash(i.toString()),scope="commercial:"+i.tenantId();var q=p("scope",scope,"user",s.userId(),"op","order.create","key",key,"hash",hash);db.update("INSERT INTO sys_control_request(scope_key,user_id,operation,request_key,request_hash) VALUES(:scope,:user,:op,:key,:hash) ON CONFLICT DO NOTHING",q);var prior=one("SELECT request_hash,result_id FROM sys_control_request WHERE scope_key=:scope AND user_id=:user AND operation=:op AND request_key=:key FOR UPDATE",q);if(!hash.equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号对应的订单内容已变化");UUID id=(UUID)prior.get("result_id");if(id==null){id=UUID.randomUUID();long amount=i.amountCents()==null?Math.multiplyExact(n(plan,"monthly_price_cents"),i.periodMonths()):i.amountCents();String no="SO"+LocalDate.now().toString().replace("-","")+id.toString().substring(0,8).toUpperCase(Locale.ROOT);db.update("INSERT INTO sys_subscription_order(id,tenant_id,plan_id,order_number,period_months,amount_cents,status,due_date,notes,created_by_user_id) VALUES(:id,:tenant,:plan,:number,:months,:amount,'PENDING',:due,:notes,:user)",p("id",id,"tenant",i.tenantId(),"plan",i.planId(),"number",no,"months",i.periodMonths(),"amount",amount,"due",i.dueDate(),"notes",text(i.notes()),"user",s.userId()));db.update("UPDATE sys_control_request SET result_id=:id WHERE scope_key=:scope AND user_id=:user AND operation=:op AND request_key=:key",p("id",id,"scope",scope,"user",s.userId(),"op","order.create","key",key));audit(s,i.tenantId(),"SUBSCRIPTION_ORDER_CREATED",id,i,trace);}return order(id);});}
 public Object paid(AuthService.Session s,UUID id,PaidInput i,UUID trace){return platform(s,()->{var raw=one("SELECT * FROM sys_subscription_order WHERE id=:id FOR UPDATE",p("id",id));if("PAID".equals(raw.get("status"))){if(text(i.externalReference()).equals(raw.get("external_reference")))return order(id);throw ApiError.conflict("订单已使用其他凭据确认收款");}if(!"PENDING".equals(raw.get("status"))||n(raw,"version")!=i.expectedVersion())throw ApiError.conflict("订单状态已变化，请刷新");UUID tenant=(UUID)raw.get("tenant_id"),plan=(UUID)raw.get("plan_id");var t=one("SELECT * FROM sys_tenant WHERE id=:id FOR UPDATE",p("id",tenant)),target=one("SELECT * FROM sys_plan WHERE id=:id AND active",p("id",plan));if(n(t,"active_member_count")>n(target,"seat_limit")||n(t,"customer_count")>n(target,"customer_limit")||n(t,"attachment_bytes")>n(target,"storage_limit_bytes"))throw ApiError.conflict("目标套餐额度低于企业当前用量");Instant now=Instant.now(),old=((Timestamp)t.get("subscription_end")).toInstant(),end=(old.isAfter(now)?old:now).atZone(ZoneId.of(String.valueOf(t.get("timezone")))).plusMonths(((Number)raw.get("period_months")).longValue()).toInstant();db.update("UPDATE sys_tenant SET plan_id=:plan,subscription_end=:end,status='ACTIVE',version=version+1 WHERE id=:tenant",p("plan",plan,"end",Timestamp.from(end),"tenant",tenant));db.update("UPDATE sys_subscription_order SET status='PAID',external_reference=:reference,paid_at=now(),version=version+1,updated_at=now() WHERE id=:id",p("reference",text(i.externalReference()),"id",id));audit(s,tenant,"SUBSCRIPTION_ORDER_PAID",id,p("reference",text(i.externalReference()),"renewedUntil",end),trace);return order(id);});}
 public Object cancel(AuthService.Session s,UUID id,CancelInput i,UUID trace){return platform(s,()->{var raw=one("SELECT * FROM sys_subscription_order WHERE id=:id FOR UPDATE",p("id",id));if("CANCELLED".equals(raw.get("status")))return order(id);if(!Set.of("DRAFT","PENDING").contains(raw.get("status"))||n(raw,"version")!=i.expectedVersion())throw ApiError.conflict("订单状态已变化，请刷新");db.update("UPDATE sys_subscription_order SET status='CANCELLED',notes=concat_ws(E'\\n',nullif(notes,''),:reason),cancelled_at=now(),version=version+1,updated_at=now() WHERE id=:id",p("reason",text(i.reason()),"id",id));audit(s,(UUID)raw.get("tenant_id"),"SUBSCRIPTION_ORDER_CANCELLED",id,i,trace);return order(id);});}
}
